import { assetById } from '../../data';

type Props = {
  id: string;
  alt: string;
  sizes?: string;
  className?: string;
  priority?: boolean;
  /** Load immediately without claiming high fetch priority (used in rails). */
  eager?: boolean;
  fit?: 'contain' | 'cover';
  position?: string;
};

/**
 * Every image on the site comes from the licence registry. Derivatives are
 * generated by scripts/optimize-assets.mjs as {id}-{width}.{avif,webp}.
 */
export function AssetImage({
  id,
  alt,
  sizes = '100vw',
  className,
  priority = false,
  eager = false,
  fit = 'cover',
  position = '50% 50%',
}: Props) {
  const asset = assetById.get(id);
  if (!asset) return null;

  const widths = asset.widths;
  const srcSet = (ext: 'avif' | 'webp') =>
    widths.map((w) => `/assets/img/${id}-${w}.${ext} ${w}w`).join(', ');
  const fallback = `/assets/img/${id}-${widths[widths.length - 1]}.webp`;

  return (
    <picture className={className}>
      <source type="image/avif" srcSet={srcSet('avif')} sizes={sizes} />
      <img
        src={fallback}
        srcSet={srcSet('webp')}
        sizes={sizes}
        alt={alt}
        loading={priority || eager ? 'eager' : 'lazy'}
        decoding={priority ? 'sync' : 'async'}
        fetchPriority={priority ? 'high' : 'auto'}
        style={{ objectFit: fit, objectPosition: position }}
      />
    </picture>
  );
}
